		It("inherits role from parameter", func() {
			_, record, err := auth.CreateAPIKey(db, user.ID, "admin key", auth.RoleAdmin, hmacSecret, nil)
			Expect(err).ToNot(HaveOccurred())
			Expect(record.Role).To(Equal(auth.RoleAdmin))
