// enqueueCall records one Enqueue with the typed payload, so a spec can tell
// an AgentChatEvent from pre-encoded bytes.
type enqueueCall struct {
	kind    messaging.WorkKind
	payload any
}

// fakeWorkQueue implements messaging.WorkQueue and records every Enqueue.
type fakeWorkQueue struct {
	calls []enqueueCall
}

func (f *fakeWorkQueue) Enqueue(_ context.Context, kind messaging.WorkKind, payload any) error {
	f.calls = append(f.calls, enqueueCall{kind: kind, payload: payload})
	return nil
}

// mockSchedulerStore implements SchedulerStore for testing.
type mockSchedulerStore struct {
	configs    []AgentConfigRecord
	lastRunErr error
	updated    []lastRunUpdate
}

type lastRunUpdate struct {
	userID string
	name   string
}

func (m *mockSchedulerStore) ListConfigs(userID string) ([]AgentConfigRecord, error) {
	if userID == "" {
		return m.configs, nil
	}
	var filtered []AgentConfigRecord
	for _, c := range m.configs {
		if c.UserID == userID {
			filtered = append(filtered, c)
		}
	}
	return filtered, nil
}

func (m *mockSchedulerStore) UpdateLastRun(userID, name string) error {
	m.updated = append(m.updated, lastRunUpdate{userID: userID, name: name})
	return m.lastRunErr
}

